Here's the result of running `cat -n` on /workspace/services/ingestion/src/sources/kulturhuset.ts:
     1	// Kulturhuset Stockholm Scraper
     2	// Fetches events from Kulturhuset's Elasticsearch API
     3	
     4	const ELASTIC_SEARCH_URL = 'https://elastic.kulturhusetstadsteatern.se/khst-events';
     5	
     6	/**
     7	 * Map Kulturhuset event to internal format
     8	 * @param {Object} event - Raw event from Elasticsearch
     9	 * @returns {Object} - Internal event format
    10	 */
    11	function mapKulturhusetEvent(event) {
    12	  const source = event._source;
    13	  
    14	  // Extract date and time
    15	  let date = '';
    16	  let time = '';
    17	  
    18	  if (source.tixStartDate) {
    19	    const startDate = new Date(source.tixStartDate);
    20	    date = startDate.toISOString().split('T')[0];
    21	    time = startDate.toTimeString().substring(0, 5);
    22	  }
    23	  
    24	  // Extract venue
    25	  const venues = source.tixVenue || [];
    26	  const venue = venues[0]?.label || 'Kulturhuset Stadsteatern';
    27	  
    28	  // Extract location/area
    29	  const locations = source.drupalLocation || [];
    30	  const area = locations[0]?.label || 'Stockholm';
    31	  
    32	  // Extract description
    33	  const descriptions = source.drupalLeadText || [];
    34	  const description = descriptions[0]?.value || '';
    35	  
    36	  // Extract URL
    37	  const url = source.drupalLink || '';
    38	  
    39	  // Extract title
    40	  const title = source.drupalTitle || source.tixName || 'Untitled Event';
    41	  
    42	  // Map category
    43	  const categories = source.drupalCategory || [];
    44	  const categoryLabel = categories[0]?.label?.toLowerCase() || '';
    45	  const category = mapCategory(categoryLabel);
    46	  
    47	  // Generate unique ID
    48	  const id = `kh-${source.tixEventId || source.drupalId || Math.random().toString(36).substr(2, 9)}`;
    49	  
    50	  return {
    51	    id,
    52	    title,
    53	    date,
    54	    time,
    55	    venue,
    56	    area,
    57	    address: '',
    58	    description: description.substring(0, 500),
    59	    url,
    60	    category,
    61	    source: 'kulturhuset',
    62	  };
    63	}
    64	
    65	/**
    66	 * Map Kulturhuset category to internal category
    67	 * @param {string} label - Category label from Kulturhuset
    68	 * @returns {string} - Internal category
    69	 */
    70	function mapCategory(label) {
    71	  const categoryMap = {
    72	    'teater': 'culture',
    73	    'musik': 'music',
    74	    'konsert': 'music',
    75	    'dans': 'culture',
    76	    'film': 'culture',
    77	    'litteratur': 'culture',
    78	    'konst': 'culture',
    79	    'utställning': 'culture',
    80	    'barn & ung': 'barn',
    81	    'barn': 'barn',
    82	    'familj': 'barn',
    83	    'sport': 'sports',
    84	    'mat & dryck': 'food',
    85	    'food': 'food',
    86	    'nattliv': 'nightlife',
    87	    'skapa': 'culture',
    88	    'för skolan': 'barn',
    89	  };
    90	  
    91	  return categoryMap[label] || 'culture';
    92	}
    93	
    94	/**
    95	 * Fetch events from Kulturhuset Elasticsearch API
    96	 * @param {Object} options - Options (limit, etc.)
    97	 * @returns {Promise<Object[]>} - Array of events
    98	 */
    99	export async function fetchKulturhusetEvents(options = {}) {
   100	  const { limit = 20, page = 0 } = options;
   101	  
   102	  const query = {
   103	    size: limit,
   104	    from: page * limit,
   105	    query: {
   106	      bool: {
   107	        must: [
   108	          {
   109	            range: {
   110	              tixStartDate: {
   111	                gte: 'now',  // Only future events
   112	              },
   113	            },
   114	          },
   115	        ],
   116	      },
   117	    },
   118	    sort: [
   119	      { tixStartDate: { order: 'asc' } },
   120	    ],
   121	  };
   122	  
   123	  try {
   124	    const response = await fetch(ELASTIC_SEARCH_URL + '/_search', {
   125	      method: 'POST',
   126	      headers: {
   127	        'Content-Type': 'application/json',
   128	        'User-Agent': 'EventPulse/1.0',
   129	      },
   130	      body: JSON.stringify(query),
   131	    });
   132	    
   133	    if (!response.ok) {
   134	      throw new Error(`Kulturhuset API error: ${response.status}`);
   135	    }
   136	    
   137	    const data = await response.json();
   138	    
   139	    if (!data.hits || !data.hits.hits) {
   140	      return [];
   141	    }
   142	    
   143	    return data.hits.hits.map(mapKulturhusetEvent);
   144	  } catch (error) {
   145	    console.error('Kulturhuset scraper error:', error);
   146	    throw error;
   147	  }
   148	}
   149	
   150	/**
   151	 * Test function - fetches and logs first 5 events
   152	 */
   153	export async function testScraper() {
   154	  console.log('Testing Kulturhuset scraper (Elasticsearch API)...');
   155	  const events = await fetchKulturhusetEvents({ limit: 5 });
   156	  
   157	  console.log(`Found ${events.length} events from Kulturhuset:`);
   158	  events.forEach((event, i) => {
   159	    console.log(`\n--- Event ${i + 1} ---`);
   160	    console.log(`Title: ${event.title}`);
   161	    console.log(`Date: ${event.date} ${event.time}`);
   162	    console.log(`Venue: ${event.venue}`);
   163	    console.log(`URL: ${event.url}`);
   164	  });
   165	  
   166	  return events;
   167	}
